Code used for the plot above <p>This is an example code and should be treated as such.</p> <pre><code># Default imports

class AwesomeStrategy(IStrategy):
    def plot_annotations(
        self, pair: str, start_date: datetime, end_date: datetime, dataframe: DataFrame, **kwargs
    ) -&gt; list[AnnotationType]:
        annotations = []
        while start_dt &lt; end_date:
            start_dt += timedelta(hours=1)
            if (start_dt.hour % 4) == 0:
                annotations.append(
                    {
                        "type": "area",
                        "label": "4h",
                        "start": start_dt,
                        "end": start_dt + timedelta(hours=1),
                        "color": "rgba(133, 133, 133, 0.4)",
                    }
                )
            elif (start_dt.hour % 2) == 0:
            price = dataframe.loc[dataframe["date"] == start_dt, ["close"]].mean()
                annotations.append(
                    {
                        "type": "area",
                        "label": "2h",
                        "start": start_dt,
                        "end": start_dt + timedelta(hours=1),
                        "y_end": price * 1.01,
                        "y_start": price * 0.99,
                        "color": "rgba(0, 255, 0, 0.4)",
                        "z_level": 5,
                    }
                )

        return annotations
